import '@servicenow/sdk/global'
import { Flow, wfa, action, trigger } from '@servicenow/sdk/automation'

// Test: ForEach with lookUpRecords - Pattern A (OutputsWithDependentTable)
Flow(
    {
        $id: Now.ID['foreach_metadata_lookup_records_flow'],
        name: 'ForEach Metadata - LookUpRecords Test',
        description: 'Tests metadata extraction from lookUpRecords action outputs',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['remote_query_trigger'] },
        {
            table: 'alm_hardware',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        const hardwareAssets = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_hardware_assets'],
                annotation: 'Lookup hardware assets',
            },
            {
                table: 'alm_hardware',
                conditions: 'active=true',
            }
        )

        wfa.flowLogic.forEach(
            wfa.dataPill(hardwareAssets.Records, 'array.object'),
            { $id: Now.ID['foreach_hardware_assets'], annotation: 'Process each asset' },
            (asset) => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_asset_info'],
                        annotation: 'Log asset information',
                    },
                    {
                        log_level: 'info',
                        log_message: `Asset: ${wfa.dataPill(asset.asset_tag, 'string')}`,
                    }
                )
            }
        )
    }
)
